    for (int i = 0; i < 256; i++) count[i] = 0;
    for (int i = 0; i < n; i++) count[(a[i].d >> 16) & 0xFF]++;
    for (int i = 1; i < 256; i++) count[i] += count[i - 1];
    for (int i = n - 1; i >= 0; i--) b[--count[(a[i].d >> 16) & 0xFF]] = a[i];

    // Pass 3
