    for (int i = 1; i <= N; i++) {
        int dx = X[i];
        int dy = Y[i];
        edges[edge_count].u = 0;
        edges[edge_count].v = i;
        edges[edge_count].d = dx * dx + dy * dy;
        edge_count++;
    }

    // Arestas entre tendas (1..N)
    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            int dx = X[i] - X[j];
            int dy = Y[i] - Y[j];
            edges[edge_count].u = i;
            edges[edge_count].v = j;
            edges[edge_count].d = dx * dx + dy * dy;
            edge_count++;
        }
    }

    radix_sort(edges, temp_edges, edge_count);

    int max_candies = 0;
    int num_changed = 0;

    for (int i = 0; i < edge_count; ) {
        int j = i;
        while (j < edge_count && edges[j].d == edges[i].d) {
            j++;
        }

        num_changed = 0;
        for (int k = i; k < j; k++) {
            int u = edges[k].u;
            int v = edges[k].v;

            if (u == 0) {
                int val = 1 + dp[v];
                if (val > max_candies) {
                    max_candies = val;
                }
            } else {
                int val_u = 1 + dp[v];
                int val_v = 1 + dp[u];

                if (next_dp[u] == 0) changed[num_changed++] = u;
                if (val_u > next_dp[u]) next_dp[u] = val_u;

                if (next_dp[v] == 0) changed[num_changed++] = v;
                if (val_v > next_dp[v]) next_dp[v] = val_v;
            }
        }

        for (int k = 0; k < num_changed; k++) {
            int u = changed[k];
            if (next_dp[u] > dp[u]) {
                dp[u] = next_dp[u];
            }
            next_dp[u] = 0;
        }

        i = j;
    }

    printf("%d\n", max_candies);

    return 0;
}
