typedef struct {
    int u;
    int v;
    long long dist;
} Edge;

typedef struct {
    int x;
    int y;
} Point;

static Point pts[2005];
static Edge edges[2005 * 2005 / 2];

// Comparador para o qsort das arestas por distância crescente
static int cmp_edge(const void *a, const void *b) {
    long long d1 = ((const Edge *)a)->dist;
    long long d2 = ((const Edge *)b)->dist;
    if (d1 < d2) return -1;
    if (d1 > d2) return 1;
    return 0;
}

static inline int max(int a, int b) {
    return a > b ? a : b;
}

static int dp[2005];
static int next_dp[2005];

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    pts[0].x = 0;
    pts[0].y = 0;

    for (int i = 1; i <= N; i++) {
        scanf("%d %d", &pts[i].x, &pts[i].y);
    }

    int edge_count = 0;
    for (int i = 0; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            long long dx = pts[i].x - pts[j].x;
            long long dy = pts[i].y - pts[j].y;
            edges[edge_count].u = i;
            edges[edge_count].v = j;
            edges[edge_count].dist = dx * dx + dy * dy;
            edge_count++;
        }
    }

    qsort(edges, edge_count, sizeof(Edge), cmp_edge);

    for (int i = 0; i <= N; i++) {
        dp[i] = 0;
        next_dp[i] = 0;
    }

    int i = 0;
    while (i < edge_count) {
        int j = i;
        while (j < edge_count && edges[j].dist == edges[i].dist) {
            j++;
        }

        // Processa todas as arestas com a mesma distância
        for (int k = i; k < j; k++) {
            int u = edges[k].u;
            int v = edges[k].v;

            if (u == 0) {
                // Origem só pode iniciar caminho para v
                next_dp[0] = max(next_dp[0], dp[v] + 1);
            } else {
                // Entre duas tendas, podemos ir de u para v ou de v para u
                next_dp[u] = max(next_dp[u], dp[v] + 1);
                next_dp[v] = max(next_dp[v], dp[u] + 1);
            }
        }

        // Aplica as atualizações nas tendas/origem afetadas
        for (int k = i; k < j; k++) {
            int u = edges[k].u;
            int v = edges[k].v;
            dp[u] = max(dp[u], next_dp[u]);
            dp[v] = max(dp[v], next_dp[v]);
        }

        i = j;
    }

    printf("%d\n", dp[0]);

    return 0;
}
